/**
 * AI provider and coding agent marks. Unlike the stroked icons in
 * `./nodes.ts` these are filled brand logos drawn edge to edge on the 24
 * unit square, each in two variants: `mono` paints in `currentColor`, and
 * `color` carries the brand's own fills. Marks whose brand colour is a
 * gradient are flattened to one representative colour.
 *
 * Geometry from LobeHub Icons (https://github.com/lobehub/lobe-icons, MIT).
 * The marks are trademarks of their owners; use them to refer to those
 * products, not to imply endorsement.
 *
 * Pure data with no runtime imports, like `./nodes.ts`.
 */

import type { IconNode } from './nodes.ts';

export interface BrandMark {
  /** Kebab-case id: the SVG file stem and the key in `icons.json`. */
  readonly name: string;
  /** The product's name as its owner writes it, used as the accessible name. */
  readonly title: string;
  /** Filled paths painted in `currentColor`. */
  readonly mono: IconNode;
  /** The same mark in brand colours, every path with its own `fill`. */
  readonly color: IconNode;
}

export type BrandVariant = 'color' | 'mono';

/** Named render sizes: 16, 24 and 32px (`BRAND_SIZES` in `./svg.ts`). */
export type BrandSize = 'sm' | 'md' | 'lg';

/** A single-colour mark in its brand colour: every path filled with `fill`. */
const paint = (node: IconNode, fill: string): IconNode =>
  node.map(([tag, attrs]) => [tag, { ...attrs, fill }]);

